// Title: Circles & Planes
// Author: Claude, ItsWesSmithYo
// Project: OneManShYo

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates to range (-1.0, 1.0) and maintain aspect ratio
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Time-based rotation
    float angle = iTime * 0.5; // Adjust rotation speed
    mat2 rotation = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
    uv *= rotation;

    // Determine which side of the plane we are on
    float side = step(0.0, uv.y); // Top (0) or Bottom (1)
    vec3 color;

    if (side == 0.0) {
        // Top Side: Zigzag pattern
        float pattern = abs(sin(20.0 * uv.y + 10.0 * iTime));
        color = vec3(pattern, 0.0, 0.5); // Blue tones
    } else {
        // Bottom Side: Circular ripple pattern
        float radius = length(uv) * 3.0; // Expand ripples
        float ripple = sin(10.0 * radius - iTime);
        ripple = abs(ripple);
        color = vec3(ripple, ripple, 0.0); // Yellow tones
    }

    // Final color
    fragColor = vec4(color, 1.0);
}
